package ru.truetv.launcher;
import android.app.*;import android.content.*;import android.os.*;import android.net.nsd.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;import ru.truetv.bridge.*;import ru.truetv.bridge.android.*;
/** Actual exported phone text Share target, mDNS capability and repeated sends to a local TLS fixture. */
public final class PhoneRepeatCheck extends Instrumentation {
 private int checks;private final StringBuilder report=new StringBuilder();private SendActivity screen;private Transfer.Receiver receiver;private NsdManager nsd;private NsdManager.RegistrationListener registration;private Context c;private volatile CountDownLatch consent;private final ArrayList<String> saved=new ArrayList<>();
 public void onCreate(Bundle b){super.onCreate(b);start();}private Object f(Object o,String n)throws Exception{Field x=o.getClass().getDeclaredField(n);x.setAccessible(true);return x.get(o);}private void main(Runnable r){runOnMainSync(r);waitForIdleSync();}private void check(boolean ok,String msg){checks++;report.append(ok?"PASS ":"FAIL ").append(msg).append('\n');if(!ok)throw new AssertionError(msg);}interface Wait{boolean ok()throws Exception;}private void until(Wait w)throws Exception{long end=SystemClock.uptimeMillis()+25000;while(!w.ok()&&SystemClock.uptimeMillis()<end)Thread.sleep(70);check(w.ok(),"await condition");}
 public void onStart(){Bundle result=new Bundle();try{c=getTargetContext();if(!Build.FINGERPRINT.contains("generic")&&!Build.MODEL.contains("Android SDK"))throw new AssertionError("VM only");Identity tv=Identity.load(new File(c.getCacheDir(),"text103-tv"));receiver=new Transfer.Receiver(tv,"Text TV",item->SharedText.target(item,value->{synchronized(saved){saved.add(value);}}),(offer,fp,code)->{if(!SharedText.isText(offer))return false;return consent.await(20,TimeUnit.SECONDS);},new Transfer.Events(){public void update(int i,String n,long b,long t){}public void finished(boolean s,String d){}});new Thread(()->{try{receiver.accept();}catch(IOException ignored){}}).start();nsd=(NsdManager)c.getSystemService(Context.NSD_SERVICE);NsdServiceInfo info=new NsdServiceInfo();info.setServiceType(Wire.TYPE);info.setServiceName("FixtureText234");info.setPort(receiver.port());info.setAttribute("id",tv.fingerprint());info.setAttribute("name","Text TV");info.setAttribute("text","1");registration=new NsdManager.RegistrationListener(){public void onServiceRegistered(NsdServiceInfo i){}public void onServiceUnregistered(NsdServiceInfo i){}public void onRegistrationFailed(NsdServiceInfo i,int e){}public void onUnregistrationFailed(NsdServiceInfo i,int e){}};nsd.registerService(info,NsdManager.PROTOCOL_DNS_SD,registration);
 String[] values={"https://example.invalid/?a=1&b=+%2F#Тест", "  00123-ABC\r\nРусский 😀\n ","vless://fixture@example.invalid:443?security=tls#Test"};
 for(int pass=0;pass<values.length;pass++){consent=new CountDownLatch(1);String value=values[pass];Intent share=new Intent(Intent.ACTION_SEND).setType(pass==2?"text/html":"text/plain");if(pass==1)share.setClipData(ClipData.newPlainText("selection",value));else share.putExtra(Intent.EXTRA_TEXT,value);if(pass==2)share.putExtra(Intent.EXTRA_HTML_TEXT,"<b>NOT THE PLAIN PAYLOAD</b>");check(!c.getPackageManager().queryIntentActivities(share,android.content.pm.PackageManager.MATCH_DEFAULT_ONLY).isEmpty(),"To TV resolves ordinary text Share intent");share.setClass(c,SendActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);if(pass==0)screen=(SendActivity)startActivitySync(share);else{ActivityMonitor monitor=new ActivityMonitor(SendActivity.class.getName(),null,false);addMonitor(monitor);share.addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP);main(()->c.startActivity(share));SendActivity previous=screen;screen=(SendActivity)waitForMonitorWithTimeout(monitor,15000);removeMonitor(monitor);check(screen!=null&&screen!=previous,"reused Share task consumes onNewIntent and creates fresh chooser");}ListView list=(ListView)f(screen,"list");until(()->list.getCount()>0);check(value.equals(f(screen,"sharedText")),"share selection extracted exactly without needing a file URI");main(()->list.performItemClick(list.getChildAt(0),0,0));until(()->SendService.active!=null&&!SendService.active.done);SendService service=SendService.active;consent.countDown();until(()->service.done);check(service.status.equals("Text sent")||service.status.equals("Текст отправлен"),"text send succeeds "+pass);until(()->((TextView)f(screen,"state")).getText().toString().equals(service.status));check(saved.size()==pass+1&&value.equals(saved.get(pass)),"full exact plaintext delivered "+pass);if(pass==2)main(()->screen.finish());}
 // A second Share arriving before the first is accepted must retain its own payload.
 consent=new CountDownLatch(1);Intent first=new Intent(Intent.ACTION_SEND).setClass(c,SendActivity.class).setType("text/plain").putExtra(Intent.EXTRA_TEXT,"queued-first").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);screen=(SendActivity)startActivitySync(first);ListView firstList=(ListView)f(screen,"list");until(()->firstList.getCount()>0);main(()->firstList.performItemClick(firstList.getChildAt(0),0,0));until(()->SendService.active!=null&&!SendService.active.done);SendService firstService=SendService.active;
 ActivityMonitor queuedMonitor=new ActivityMonitor(SendActivity.class.getName(),null,false);addMonitor(queuedMonitor);Intent second=new Intent(first).putExtra(Intent.EXTRA_TEXT,"queued-second").addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP);main(()->c.startActivity(second));screen=(SendActivity)waitForMonitorWithTimeout(queuedMonitor,15000);removeMonitor(queuedMonitor);check(screen!=null&&"queued-second".equals(f(screen,"sharedText")),"new Share payload survives while previous send is pending");check((Boolean)f(screen,"waitingForPrevious"),"new chooser waits for active transfer");consent.countDown();until(()->firstService.done);ListView next=(ListView)f(screen,"list");until(()->next.getVisibility()==android.view.View.VISIBLE&&next.getCount()>0);check(!((Boolean)f(screen,"waitingForPrevious")),"chooser becomes available when previous send completes");main(()->next.performItemClick(next.getChildAt(0),0,0));until(()->saved.size()==5);check("queued-first".equals(saved.get(3))&&"queued-second".equals(saved.get(4)),"both queued Share payloads delivered once in order");
 result.putBoolean("passed",true);
 }catch(Throwable e){StringWriter w=new StringWriter();e.printStackTrace(new PrintWriter(w));report.append(w);result.putBoolean("passed",false);}finally{try{if(consent!=null)consent.countDown();if(screen!=null)main(screen::finish);if(SendService.active!=null)main(()->SendService.active.cancel());if(receiver!=null)receiver.close();if(nsd!=null&&registration!=null)nsd.unregisterService(registration);}catch(Exception e){report.append("CLEANUP ").append(e);}}result.putString("report",report+"Checks="+checks);finish(result.getBoolean("passed")?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
